document.addEventListener('change', async event => {
	const order=event.target.closest('#p25-order');if(order){state.p25Order=order.value;localStorage.setItem('gpsdr-p25-order',order.value);renderDecoders();return;}
	const p25Rate=event.target.closest('#p25-live-rate');if(p25Rate){const profile=state.profiles.find(item=>item.id===(state.p25Status?.profileID||state.status?.activeProfileID));if(!profile)return toast('Start or select a P25 profile first',true);try{const wasRunning=state.status?.running&&state.status.activeProfileID===profile.id;let updated=profile.builtIn?await api('/api/profiles/duplicate?id='+encodeURIComponent(profile.id),{method:'POST'}):structuredClone(profile);updated.settings||={};updated.settings.p25SampleRateHz=Number(p25Rate.value)||0;updated=await api('/api/profiles',{method:'POST',body:JSON.stringify(updated)});if(wasRunning){await api('/api/control/stop',{method:'POST',body:'{}'});await api('/api/control/start',{method:'POST',body:JSON.stringify({profileID:updated.id})});}state.selectedProfileID=updated.id;toast(profile.builtIn?'Editable profile created Â· capture width applied':'P25 capture width applied');await refreshAll();}catch(error){toast(error.message,true);}return;}
	const volume=event.target.closest('.mixer-volume'),pan=event.target.closest('.mixer-pan');if(!volume&&!pan)return;const slider=volume||pan,row=slider.closest('[data-mixer-id]');
	try{await api('/api/mixer',{method:'POST',body:JSON.stringify({id:row.dataset.mixerId,...(volume?{volume:Number(slider.value)}:{pan:Number(slider.value)})})});await refreshAll();}catch(error){toast(error.message,true);}
});

$('#add-range').addEventListener('click',()=>{state.editingProfile.ranges.push({id:crypto.randomUUID(),name:'New range',startHz:144e6,endHz:148e6,stepHz:12500,dwellMilliseconds:180,preferredMode:'auto',decoder:null,enabled:true});renderEditorRows();});
